arguments.command:
python3 - <<'EOF'
p='src/thread.test.ts'
s=open(p).read()
s=s.replace(" console.log(JSON.stringify(Object.keys(context)), context.tools?.length, context.systemPrompt?.slice(0,300));","")
s=s.replace("""const toolNames = (context: ModelContext) =>
	(context.tools ?? []).map((t) => t.name);
const descriptionOf = (context: ModelContext, name: string) =>
	context.tools?.find((t) => t.name === name)?.description;
""","""/** The tools the model is offered: the system messages' tools, added and removed in order. */
function toolsOf(context: ModelContext): Tool[] {
	const tools = new Map<string, Tool>();
	for (const message of context.messages) {
		if (message.role === "system") {
			for (const { name } of message.toolsRemoved ?? []) {
				tools.delete(name);
			}
			for (const added of message.toolsAdded ?? []) {
				tools.set(added.name, added);
			}
		}
	}
	return [...tools.values()];
}

const toolNames = (context: ModelContext) => toolsOf(context).map((t) => t.name);
const descriptionOf = (context: ModelContext, name: string) =>
	toolsOf(context).find((t) => t.name === name)?.description;
/** The system prompt and its sections, as JSON. */
const systemText = (context: ModelContext) =>
	JSON.stringify(context.messages.filter((m) => m.role === "system"));
""")
s=s.replace("context.systemPrompt","systemText(context)")
s=s.replace('import type { Context as ModelContext } from "@earendil-works/pi-ai";','import type { Context as ModelContext, Tool } from "@earendil-works/pi-ai";')
open(p,'w').write(s)
EOF
npx vitest run src/thread.test.ts 2>&1 | grep -v "^::" | tail -30
